export function getKeywordsForPlatform(platformId: string, lang: 'es' | 'en'): string {
	const platform = platformKeywords[platformId] || platformKeywords.twitch;
	const list = lang === 'es' ? platform.es : platform.en;
	return list.join(', ');
}
